KOL_st.name='KOL'; 
KOL_st.lat=22.56;
KOL_st.lon=88.36;
KOL_st.alt=0000;
KOL_st.env='Con';
KOL_st.footp='U';
%%
% data imported via the import tool from matlab

KOL_rd_h.Properties.DimensionNames{1}='Time';
KOL_rd_h.Properties.VariableNames{2}='Ba1_A';
KOL_rd_h.Properties.VariableNames{3}='Ba2_A';
KOL_rd_h.Properties.VariableNames{4}='Ba3_A';
KOL_rd_h.Properties.VariableNames{5}='Ba4_A';
KOL_rd_h.Properties.VariableNames{6}='Ba5_A';
KOL_rd_h.Properties.VariableNames{7}='Ba6_A';
KOL_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(KOL_rd_h);
%%
KOL_rd=retime(KOL_rd_h,'daily',@nanmedian);
%%
datevec(KOL_rd.Time(1)) % begin in 2016,  %[output:0dfcdb0d]
datevec(KOL_rd.Time(end)) % end in 2019 too short %[output:8090d980]
plotFigControl(KOL_rd,KOL_st.name);  %[output:1c00bffa] %[output:526857ac] %[output:989a19d1] %[output:68a33d0b] %[output:9f956a67] %[output:46657cce]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
KOL_cal=compute_exp_D(KOL_rd,names_abs,lambdaAE7); %[output:6aa6a84b] %[output:60b0395f] %[output:05b119f1]
plotFigControl_cal(KOL_cal,KOL_st.name); %[output:8826973b] %[output:34ca78bb] %[output:930bc8fb]
%%
%HOMOGENEITY

break_KOL_abs_BP=change_point_analysis_Def(KOL_rd,names_abs,0.05,'KOL','Absorption'); %[output:6749b5c0] %[output:89ca0862] %[output:7b75582c] %[output:1dc16ab1] %[output:826f7880] %[output:2baaf913]
T_KOL_abs_BP=make_table_breakpoints_def(break_KOL_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:88df2a97]
break_KOL_expA_BP=change_point_analysis_Def(KOL_cal,names_expA,0.05,'KOL','Absorption exponent'); %[output:09b3a098] %[output:68af9778] %[output:789bf7ca] %[output:25fe26d6]
T_KOL_expA_BP=make_table_breakpoints_def(break_KOL_expA_BP);


